int maxCoins(vector<int>& nums) {
    int n = nums.size() + 2;
    vector<int> balloons(n);
    balloons[0] = balloons[n - 1] = 1;
    for (int i = 0; i < (int)nums.size(); i++) balloons[i + 1] = nums[i];
    vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int length = 2; length < n; length++) {                   // range length, smallest first
        for (int left = 0; left + length < n; left++) {
            int right = left + length;
            int best = 0;
            for (int k = left + 1; k < right; k++) {                   // try every LAST-burst balloon
                int coins = balloons[left] * balloons[k] * balloons[right] + dp[left][k] + dp[k][right];
                best = max(best, coins);
            }
            dp[left][right] = best;
        }
    }
    return dp[0][n - 1];
}
